from math import comb

def stirling2(n, k):
    """Calculates the Stirling number of the second kind S(n, k)."""
    if k < 0 or k > n:
        return 0
    if k == 0:
        return 0 if n > 0 else 1
    if k == 1 or k == n:
        return 1

    # Using the inclusion-exclusion formula
    # S(n, k) = 1/k! * sum_{j=0}^{k} (-1)^j * comb(k, j) * (k-j)^n

    result = 0
    for j in range(k + 1):
        term = ((-1)**j) * comb(k, j) * ((k - j)**n)
        result += term

    return result // factorial(k)

def factorial(k):
    res = 1
    for i in range(1, k + 1):
        res *= i
    return res

N = 15
total_count = 0

for m in range(1, N + 1):
    S_nm = stirling2(N, m)
    C_m_15_approx = factorial(m) * S_nm
    total_count += C_m_15_approx

print(total_count)

def is_kawaii(sequence):
    N = len(sequence)
    S = set(sequence)

    # Check conditions for k >= 2
    for k in range(2, max(S) + 1):
        if k in S:
            # Condition 1: k-1 must appear
            if k - 1 not in S:
                return False

            # Condition 2: F_{k-1} < L_k

            # Find first occurrence of k-1
            F_k_minus_1 = -1
            for i in range(N):
                if sequence[i] == k - 1:
                    F_k_minus_1 = i + 1 # 1-based indexing
                    break

            # Find last occurrence of k
            L_k = -1
            for i in range(N - 1, -1, -1):
                if sequence[i] == k:
                    L_k = i + 1 # 1-based indexing
                    break

            if F_k_minus_1 >= L_k:
                return False

    return True

# N=3, m=2. Sequences in {1, 2}^3 (8 total)
sequences = []
import itertools
for p in itertools.product([1, 2], repeat=3):
    sequences.append(list(p))

kawaii_count = 0
for seq in sequences:
    if is_kawaii(seq):
        kawaii_count += 1
        # print(f"Kawaii: {seq}")

print(f"Count for N=3, m=2: {kawaii_count}")

