from math import factorial
from itertools import combinations

N = 15
T_approx = 0

def combinations_nk(n, k):
    if k < 0 or k > n:
        return 0
    return factorial(n) // (factorial(k) * factorial(n - k))

for m in range(1, N + 1):
    sum_m = 0
    # m! * S(N, m) = Sum_{k=0}^m (-1)^(m-k) * C(m, k) * k^N
    for k in range(m + 1):
        term = ((-1)**(m - k)) * combinations_nk(m, k) * (k**N)
        sum_m += term

    T_approx += sum_m

print(T_approx)
